#define CK(x) do{auto e=(x);if(e!=cudaSuccess)throw std::runtime_error(cudaGetErrorString(e));}while(0)
using I=interval_gpu<double>;
__global__ void echo_inputs(double*out,I domain){int i=blockIdx.x*blockDim.x+threadIdx.x;if(i<THREADS){I a=f(I(1.),i);out[2*i]=a.lower();out[2*i+1]=a.upper();if(i==0){out[2*THREADS]=domain.lower();out[2*THREADS+1]=domain.upper();rounded_arith<double>r;out[2*THREADS+2]=r.add_up(1.,0x1p-53);out[2*THREADS+3]=r.add_down(1.,0x1.8p-52);}}}
template<class X>struct Buf{X*base=nullptr,*d=nullptr;size_t n;Buf(size_t n):n(n){CK(cudaMalloc(&base,(n+64)*sizeof(X)));d=base+32;}~Buf(){cudaFree(base);}void reset(){CK(cudaMemset(base,165,(n+64)*sizeof(X)));}std::vector<X>host(){std::vector<X>x(n+64);CK(cudaMemcpy(x.data(),base,x.size()*sizeof(X),cudaMemcpyDeviceToHost));return x;}};
void write(const std::string&p,const void*data,size_t n){std::ofstream f(p,std::ios::binary);f.write((const char*)data,n);if(!f)throw std::runtime_error("raw output write failure");}
int main(int argc,char**argv){try{if(argc!=2)throw std::runtime_error("persistent raw path required");std::string folder=argv[1];Buf<I>out(size_t(THREADS)*DEPTH_RESULT);Buf<int>counts(THREADS);Buf<double>echo(2*THREADS+4);I domain(double(.01f),4.);auto reset=[&](){out.reset();counts.reset();echo.reset();CK(cudaDeviceSynchronize());};auto run=[&](int choice){CK(cudaDeviceSynchronize());auto t=std::chrono::steady_clock::now();test_interval_newton<double><<<GRID_SIZE,BLOCK_SIZE>>>(out.d,counts.d,domain,choice);CK(cudaGetLastError());CK(cudaDeviceSynchronize());return std::chrono::duration<double>(std::chrono::steady_clock::now()-t).count();};for(int ch=0;ch<2;ch++){reset();run(ch);}for(int trial=1;trial<=5;trial++){std::vector<double>prefix,values;double seconds=0;bool ok=true;for(int ch=0;ch<2;ch++){reset();echo_inputs<<<GRID_SIZE,BLOCK_SIZE>>>(echo.d,domain);CK(cudaGetLastError());CK(cudaDeviceSynchronize());auto initial=echo.host();for(size_t i=32;i<32+echo.n;i++)prefix.push_back(initial[i]);prefix.push_back(ch);prefix.push_back(THREADS);prefix.push_back(1);prefix.push_back(GRID_SIZE);prefix.push_back(BLOCK_SIZE);seconds+=run(ch);auto result=out.host();auto n=counts.host();auto e=echo.host();auto coverage=check_coverage(result.data()+32,n.data()+32);ok&=coverage.pass;fprintf(stderr,"trial%d choice%d exactrootcoverage_missing%d extra_candidates%d\n",trial,ch,coverage.missing,coverage.extra);std::vector<unsigned char>guards;auto guard=[&](auto&a){using X=typename std::decay_t<decltype(a)>::value_type;auto b=(unsigned char*)a.data();guards.insert(guards.end(),b,b+32*sizeof(X));guards.insert(guards.end(),b+(a.size()-32)*sizeof(X),b+a.size()*sizeof(X));};guard(result);guard(n);guard(e);bool gok=std::all_of(guards.begin(),guards.end(),[](auto x){return x==165;});ok&=gok;for(int i=0;i<THREADS;i++){int k=n[32+i];values.push_back(k);if(k<0||k>DEPTH_RESULT){ok=false;continue;}std::vector<std::pair<double,double>>iv;for(int j=0;j<k;j++){auto x=result[32+size_t(j)*THREADS+i];if(!std::isfinite(x.lower())||!std::isfinite(x.upper())||x.lower()>x.upper())ok=false;iv.emplace_back(x.lower(),x.upper());}std::sort(iv.begin(),iv.end());for(auto x:iv){values.push_back(x.first);values.push_back(x.second);}}std::string path=folder+"/cuda_"+std::to_string(getpid())+"_trial"+std::to_string(trial)+"_choice"+std::to_string(ch);write(path+".intervals.bin",result.data(),result.size()*sizeof(I));write(path+".counts.i32",n.data(),n.size()*4);write(path+".echo.f64",e.data(),e.size()*8);write(path+".guards.u8",guards.data(),guards.size());printf("STUDY_RAW_ARTIFACT {\"trial\":%d,\"choice\":%d,\"path\":\"%s\",\"result_bytes\":%zu,\"guard_bytes\":%zu}\n",trial,ch,path.c_str(),result.size()*sizeof(I),guards.size());}prefix.insert(prefix.end(),values.begin(),values.end());std::string path="trial"+std::to_string(trial)+".bin";write(path,prefix.data(),prefix.size()*8);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":null,\"max_rel_error\":null,\"timing_region\":\"sum2_full65536equation_Newton_variants_kernel_and_contextcompletion\",\"jit_excluded\":true,\"internal_repeats\":1,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,seconds,ok?"true":"false",prefix.size(),path.c_str(),prefix.size());fflush(stdout);}return 0;}catch(const std::exception&e){fprintf(stderr,"%s\n",e.what());return 1;}}
